function enableAllParticipantResources(){const resourceIds=db.resources.map(resource=>resource.id);db.participantResources=db.participants.flatMap(person=>resourceIds.map(resourceId=>({participantId:person.id,resourceId})))}
function enableCurrentParticipantResourcesOnce(){if(localStorage.getItem(RESOURCE_ENABLEMENT_MIGRATION_KEY))return;enableAllParticipantResources();localStorage.setItem(RESOURCE_ENABLEMENT_MIGRATION_KEY,'done')}
function minimumForResource(resource){return Math.max(1,Math.floor(Number(resource?.minParticipants)||2))}
function maximumForResource(resource){return Math.max(minimumForResource(resource),Math.floor(Number(resource?.maxParticipants)||minimumForResource(resource)))}
function normalizeParticipantData(){let corrections=0;db.participants.forEach(person=>{const legacyGender=person.gender==='Masculino'?'Hombre':person.gender==='Femenino'?'Mujer':person.gender;const gender=genders.includes(legacyGender)?legacyGender:'';if(person.gender!==gender){person.gender=gender;corrections++}person.spouseId??=''});db.participants.forEach(person=>{if(!person.spouseId)return;const spouse=db.participants.find(candidate=>candidate.id===person.spouseId);if(!spouse||spouse.id===person.id||!person.gender||!spouse.gender||person.gender===spouse.gender){person.spouseId='';corrections++}});db.participants.forEach(person=>{if(!person.spouseId)return;const spouse=db.participants.find(candidate=>candidate.id===person.spouseId);if(!spouse)return;if(spouse.spouseId&&spouse.spouseId!==person.id){person.spouseId='';corrections++;return}spouse.spouseId=person.id});return corrections}
db.resources.forEach(resource=>{resource.minParticipants=minimumForResource(resource);const assigned=db.programs.flatMap(program=>program.assignments||[]).filter(assignment=>assignment.resourceId===resource.id).reduce((highest,assignment)=>Math.max(highest,assignment.participantIds?.length||0),0);resource.maxParticipants=Math.max(resource.minParticipants,Math.floor(Number(resource.maxParticipants)||0),assigned)});
