const formatMonth=month=>{const [year,number]=String(month).split('-').map(Number);if(!Number.isFinite(year)||!Number.isFinite(number))return month;const name=new Date(year,number-1,1).toLocaleDateString('es-MX',{month:'long'});return `${name.charAt(0).toUpperCase()}${name.slice(1)} ${year}`};
