const programSignature=p=>JSON.stringify({month:p.month,assignments:p.assignments.map(a=>({id:a.id,date:a.date,turnId:a.turnId,resourceId:a.resourceId,participantIds:[...a.participantIds].sort(),protected:!!a.protected,origin:a.origin}))});
const reviewState=p=>!p.reviewedAt?'editing':p.reviewedSignature===programSignature(p)?'reviewed':'changed';
const reviewLabel=p=>({editing:'En edición',reviewed:'Revisado',changed:'Cambios sin revisar'})[reviewState(p)];
function markProgramReviewed(id){const program=db.programs.find(item=>item.id===id);if(!program)return;program.reviewedAt=now();program.reviewedSignature=programSignature(program);program.updatedAt=now();save('Programa marcado como revisado',program.month);programNotice={programId:program.id,message:'Programa marcado como revisado.'};openProgram(program.id);programNotice=null}
function syncProgramStatus(p){p.status=reviewLabel(p);return p.status}
const formatDateTime=value=>new Date(value).toLocaleString('es-MX',{dateStyle:'medium',timeStyle:'short'});
const pendingForProgram=p=>p.assignments.filter(a=>a.participantIds.length<Math.max(1,db.resources.find(r=>r.id===a.resourceId)?.minParticipants??2)).length;
function autoAssignProgram(id){const p=db.programs.find(item=>item.id===id);if(!p)return;const before=pendingForProgram(p),generated=generate(p.month);let changed=0;p.assignments=p.assignments.map(current=>{const minimum=Math.max(1,db.resources.find(r=>r.id===current.resourceId)?.minParticipants??2);if(current.protected||current.participantIds.length>=minimum)return current;const proposal=generated.find(item=>item.date===current.date&&item.turnId===current.turnId&&item.resourceId===current.resourceId);if(!proposal||proposal.participantIds.join('|')===current.participantIds.join('|'))return current;changed++;return {...current,participantIds:proposal.participantIds}});p.updatedAt=now();const remaining=pendingForProgram(p),covered=Math.max(0,before-remaining);programNotice={programId:p.id,message:covered?`Se completaron ${covered} asignaciones; quedan ${remaining} pendientes.`:`No se encontraron nuevas asignaciones automáticas. Quedan ${remaining} pendientes.`};save('Autoasignación de pendientes',`${covered} asignaciones cubiertas`);openProgram(p.id)}
function printProgram(id){const p=db.programs.find(item=>item.id===id);if(!p)return;programScope='all';openProgram(p.id);requestAnimationFrame(()=>window.print())}
function enhanceProgramToolbar(){const tools=document.querySelector('.program-tools'),auto=tools?.querySelector('[data-action="regenerate"]');if(!tools||!auto)return;const p=db.programs.find(item=>item.id===auto.dataset.id);if(!p)return;const state=reviewState(p),status=document.querySelector('.program-head .tag'),reviewedAt=p.reviewedAt?formatDateTime(p.reviewedAt):'';if(status){status.className=`review-tag review-${state}`;status.textContent=reviewLabel(p);status.insertAdjacentHTML('afterend',state==='reviewed'?`<small class="review-meta">Revisado el ${esc(reviewedAt)}</small>`:state==='changed'?`<small class="review-meta">Última revisión: ${esc(reviewedAt)}</small>`:'')}tools.innerHTML=`<button type="button" class="primary" title="Autoasigna únicamente los turnos pendientes." data-auto>Autoasignar</button><button type="button" ${state==='reviewed'?'disabled':''} title="${state==='reviewed'?'El programa ya coincide con la última revisión.':'Marca esta versión del programa como revisada.'}" data-review>${state==='reviewed'?'Revisado ✓':'Marcar como revisado'}</button><details class="export-menu"><summary title="Exporta el programa en cualquier momento.">Exportar ▾</summary><div><button type="button" data-export>Descargar CSV</button><button type="button" data-print>Imprimir / PDF</button></div></details>`;tools.querySelector('[data-auto]').onclick=()=>autoAssignProgram(p.id);tools.querySelector('[data-review]').onclick=()=>markProgramReviewed(p.id);tools.querySelector('[data-export]').onclick=()=>exportCsv(p.id);tools.querySelector('[data-print]').onclick=()=>printProgram(p.id);const message=document.querySelector('.program-message');if(message&&programNotice?.programId===p.id)message.insertAdjacentHTML('afterend',`<p class="auto-result">${esc(programNotice.message)}</p>`)}
