function modal(html,submit){const el=document.querySelector('#modal');el.style.height='';el.style.maxHeight='';el.innerHTML=`<form method="dialog" class="modal" id="modalForm">${html}</form>`;el.querySelectorAll('.toolbar button[data-close]').forEach(button=>{if(button.textContent.trim()!=='Cerrar')return;button.className='icon-button';button.title='Cerrar';button.setAttribute('aria-label','Cerrar');button.textContent='×'});const grid=el.querySelector('.availability-grid');el.classList.toggle('compact-form-modal',!grid);el.showModal();if(grid){const name=el.querySelector('[name="name"]')?.value,person=db.participants.find(x=>x.name===name);grid.insertAdjacentHTML('afterend',`<div class="availability-heading frequency-heading"><div><span class="eyebrow">Frecuencia</span><h3>Recurrencia</h3></div><div class="frequency-control"><input name="frequencyCount" aria-label="Veces por frecuencia" type="number" min="1" max="52" step="1" value="${person?.frequencyCount??1}" required><span>veces cada</span><input name="frequencyWeeks" aria-label="Semanas por frecuencia" type="number" min="1" max="52" step="1" value="${person?.frequencyWeeks??1}" required><span>semanas</span></div></div>`)}const form=el.querySelector('#modalForm'),footer=form?.querySelector('.modal-actions');if(form&&footer){const content=document.createElement('div');content.className='modal-scroll-content';[...form.children].filter(node=>node!==footer&&!node.matches('.toolbar,.participant-tabs')).forEach(node=>content.append(node));form.insertBefore(content,footer);content.scrollTop=0}el.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>el.close());el.querySelector('#modalForm').onsubmit=e=>{e.preventDefault();const formData=new FormData(e.currentTarget);submit(formData,el);if(grid){const person=db.participants.find(x=>x.name===formData.get('name'));if(person){person.frequencyCount=Math.max(1,Math.min(52,Math.floor(Number(formData.get('frequencyCount'))||1)));person.frequencyWeeks=Math.max(1,Math.min(52,Math.floor(Number(formData.get('frequencyWeeks'))||1)));localStorage.setItem(KEY,JSON.stringify(db))}}}}
function confirmDialog({title,message,confirmLabel='Eliminar',onConfirm}){const el=document.querySelector('#modal');el.classList.remove('compact-form-modal');el.style.height='fit-content';el.style.maxHeight='calc(100vh - 32px)';el.innerHTML=`<form method="dialog" class="modal confirm-modal"><div class="confirm-icon">!</div><div class="confirm-copy"><span class="eyebrow">Confirmación</span><h2>${esc(title)}</h2><p>${esc(message)}</p></div><div class="modal-actions"><button type="button" data-close>Cancelar</button><button type="button" class="danger confirm-action" data-confirm>${esc(confirmLabel)}</button></div></form>`;el.showModal();el.style.height=`${el.firstElementChild.getBoundingClientRect().height}px`;el.querySelector('[data-close]').onclick=()=>el.close();el.querySelector('[data-confirm]').onclick=()=>{onConfirm();el.close()};el.querySelector('[data-close]').focus()}
function noticeDialog({title='Aviso',message}){const el=document.querySelector('#modal');el.classList.remove('compact-form-modal');el.style.height='fit-content';el.style.maxHeight='calc(100vh - 32px)';el.innerHTML=`<section class="modal confirm-modal notice-modal"><div class="confirm-icon">i</div><div class="confirm-copy"><span class="eyebrow">Información</span><h2>${esc(title)}</h2><p>${esc(message)}</p></div><div class="modal-actions"><button type="button" class="primary" data-close>Entendido</button></div></section>`;el.showModal();el.style.height=`${el.firstElementChild.getBoundingClientRect().height}px`;el.querySelector('[data-close]').onclick=()=>el.close();el.querySelector('[data-close]').focus()}
function formError(message){const form=document.querySelector('#modalForm');if(!form)return noticeDialog({title:'Revisa la información',message});let error=form.querySelector('.form-error');if(!error){error=document.createElement('p');error.className='form-error';form.querySelector('.modal-actions')?.before(error)}error.textContent=message;error.focus?.()}
const selected=(yes)=>yes?'selected':'';const checked=(yes)=>yes?'checked':'';
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,id}=b.dataset;if(action==='clearAvailability'){e.stopImmediatePropagation();const person=db.participants.find(x=>x.id===id);return confirmDialog({title:'Eliminar disponibilidad',message:'Se quitarán todos los horarios disponibles de este participante.',onConfirm:()=>{db.availabilities=db.availabilities.filter(x=>x.participantId!==id);save('Eliminación de disponibilidad',person?.name);availability()}})}if(action==='deleteState'){e.stopImmediatePropagation();const state=db.states.find(x=>x.id===id);if(!state)return;if(db.participants.some(p=>p.stateId===id))return noticeDialog({title:'No se puede eliminar el estado',message:'Este estado está asignado a participantes. Primero asigna otro estado a esas personas.'});return confirmDialog({title:'Eliminar estado',message:`¿Quieres eliminar “${state.name}”? Esta acción no se puede deshacer.`,onConfirm:()=>{db.states=db.states.filter(x=>x.id!==id);save('Eliminación de estado',state.name);states()}})}},true);
document.addEventListener('click',e=>{const b=e.target.closest('[data-action="setProgramScope"]');if(!b)return;e.stopImmediatePropagation();programScope=b.dataset.scope;const program=db.programs.find(item=>item.id===b.dataset.pid),matches=program&&classifyProgramAssignments(program)[programScope];if(program&&programLayout==='calendar'&&matches?.length){const current=selectedCalendarWeek(program).selected,weekEnd=addCalendarDays(current,6),hasVisible=matches.some(assignment=>{const date=calendarDate(assignment.date);return date>=current&&date<=weekEnd});if(!hasVisible)programCalendarWeekStart=calendarLocalIso(calendarMonday(calendarDate(matches[0].date)))}openProgram(b.dataset.pid)},true);
const stateFor=person=>db.states.find(state=>state.id===person.stateId)||db.states[0];
const normalizeText=value=>String(value??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLocaleLowerCase();
function importReportParticipants(){if(localStorage.getItem(REPORT_IMPORT_KEY))return;const dayIndexes=new Map(days.map((day,index)=>[normalizeText(day),index]));let added=0,updated=0,availabilityCount=0;for(const row of reportRows){let person=db.participants.find(item=>normalizeText(item.name)===normalizeText(row.name));if(!person){person={id:uid(),name:row.name,active:true,typeIds:[],stateId:'state-active'};db.participants.push(person);added++}else updated++;person.frequencyCount=row.frequencyCount;person.frequencyWeeks=row.frequencyWeeks;const turnIds=db.turns.filter(turn=>row.turnRanges.some(([start,end])=>turn.start===start&&turn.end===end)).map(turn=>turn.id),selectedDays=row.dayNames.map(day=>dayIndexes.get(normalizeText(day))).filter(day=>day!==undefined);if(turnIds.length&&selectedDays.length){db.availabilities=db.availabilities.filter(slot=>slot.participantId!==person.id);for(const turnId of turnIds)for(const day of selectedDays){db.availabilities.push({participantId:person.id,turnId,day});availabilityCount++}}}localStorage.setItem(REPORT_IMPORT_KEY,'done');save('Importación de informe','51 participantes; disponibilidades coincidentes: '+availabilityCount+' asignaciones')}
importReportParticipants();
function importReportResources(){if(localStorage.getItem(REPORT_RESOURCE_IMPORT_KEY))return;const codeFor=resource=>{const text=normalizeText(`${resource.name} ${resource.location}`);if(/\\bc1\\b/.test(text)||text.includes('o primera y concordia'))return'c1';if(/\\bc2\\b/.test(text)||text.includes('plaza metroplex'))return'c2';if(/\\bex1\\b/.test(text)||text.includes('plaza venecia'))return'ex1'};const resourcesByCode=new Map(db.resources.map(resource=>[codeFor(resource),resource.id]).filter(([code])=>code));let participantsFound=0,assignments=0,unmatchedCodes=0;for(const row of reportResources){const person=db.participants.find(item=>normalizeText(item.name)===normalizeText(row.name));if(!person)continue;participantsFound++;db.participantResources=db.participantResources.filter(item=>item.participantId!==person.id);for(const code of row.resourceCodes){const resourceId=resourcesByCode.get(code.toLowerCase());if(!resourceId){unmatchedCodes++;continue}db.participantResources.push({participantId:person.id,resourceId});assignments++}}localStorage.setItem(REPORT_RESOURCE_IMPORT_KEY,'done');save('Asignación de puntos desde informe',`${participantsFound} participantes; ${assignments} asignaciones; códigos sin coincidencia: ${unmatchedCodes}`)}
importReportResources();
const tagFor=typeId=>db.types.find(type=>type.id===typeId);
function dashboard(){shell(`<div class="card"><div class="toolbar"><div><h2>Inicio</h2><p class="muted">Gestiona tus programas locales sin conexión.</p></div><button class="primary" data-action="newProgram">Crear programa</button></div></div><div class="grid"><div class="card"><div class="stat">${db.participants.filter(x=>x.active).length}</div>Participantes activos</div><div class="card"><div class="stat">${db.turns.filter(x=>x.active).length}</div>Turnos activos</div><div class="card"><div class="stat">${db.resources.filter(x=>x.active).length}</div>Puntos activos</div><div class="card"><div class="stat">${db.programs.length}</div>Programas</div></div><div class="card"><h3>Programas existentes</h3>${db.programs.length?`<div class="tablewrap"><table><tr><th>Programa</th><th>Estado</th><th>Actualizado</th><th class="program-actions-header">Acciones</th></tr>${db.programs.map(p=>`<tr><td><button class="program-link" data-action="openProgram" data-id="${p.id}" title="Editar programa ${esc(formatMonth(p.month))}">${esc(formatMonth(p.month))}</button></td><td>${esc(p.status)}</td><td>${new Date(p.updatedAt).toLocaleString()}</td><td class="program-actions"><div class="row-actions"><button class="icon-button" title="Abrir programa" aria-label="Abrir programa ${esc(formatMonth(p.month))}" data-action="openProgram" data-id="${p.id}">↗</button><button class="icon-button" title="Exportar CSV" aria-label="Exportar CSV ${esc(formatMonth(p.month))}" data-action="export" data-id="${p.id}">↓</button><button class="icon-button icon-danger" title="Eliminar programa" aria-label="Eliminar programa ${esc(formatMonth(p.month))}" data-action="deleteProgram" data-id="${p.id}">⌫</button></div></td></tr>`).join('')}</table></div>`:'<p class="muted">Aún no hay programas.</p>'}</div>`)}
function legacyParticipantDialog(p){const slots=p?db.availabilities.filter(a=>a.participantId===p.id):[],resourceIds=p?db.participantResources.filter(x=>x.participantId===p.id).map(x=>x.resourceId):[],typeIds=p?.typeIds??[],currentState=stateFor(p||{});modal(`<div class="toolbar"><div><span class="eyebrow">Ficha de participante</span><h2>${p?'Editar':'Nuevo'} participante</h2></div><button type="button" class="icon-button" title="Cerrar" aria-label="Cerrar" data-close>×</button></div><div class="form"><label>Nombre<input name="name" required value="${esc(p?.name)}"></label><label>Estado<select name="stateId">${db.states.map(s=>`<option value="${s.id}" ${selected(currentState?.id===s.id)}>${esc(s.name)}</option>`).join('')}</select></label></div><div class="availability-heading"><div><h3>Etiquetas</h3></div><p class="muted small">Puedes asignar una o varias etiquetas.</p></div><div class="type-options">${db.types.map(t=>`<label class="type-option" style="--tag-color:${esc(t.color)}"><input type="checkbox" name="type" value="${t.id}" ${checked(typeIds.includes(t.id))}><span>${esc(t.name)}</span></label>`).join('')||'<p class="muted">Crea etiquetas para poder asignarlas.</p>'}</div><div class="availability-heading"><div><h3>Lugares asignables</h3></div><p class="muted small">Selecciona los puntos en los que esta persona puede participar.</p></div><div class="resource-options">${db.resources.filter(r=>r.active).map(r=>`<label class="resource-option"><input type="checkbox" name="resource" value="${r.id}" ${checked(resourceIds.includes(r.id))}><span class="resource-marker">⌖</span><span><strong>${esc(r.name)}</strong></span></label>`).join('')||'<p class="muted">No hay puntos activos.</p>'}</div><div class="availability-heading"><div><span class="eyebrow">Calendario semanal</span><h3>Disponibilidad de horarios</h3></div><p class="muted small">Marca únicamente los días disponibles.</p></div><div class="availability-grid">${db.turns.filter(t=>t.active).map(t=>`<section class="turn-card"><div class="turn-card-title"><span class="turn-icon">◷</span><div><strong>${esc(t.name)}</strong><small>${t.start} – ${t.end}</small></div></div><div class="day-options">${days.map((d,i)=>`<label class="day-option"><input type="checkbox" name="slot" value="${t.id}|${i}" ${checked(slots.some(a=>a.turnId===t.id&&a.day===i))}><span>${d}</span></label>`).join('')}</div></section>`).join('')}</div><div class="modal-actions"><button type="button" data-close>Cancelar</button><button class="primary">Guardar</button></div>`,(f,m)=>{const fresh=!p,person=p||{id:uid()},state=db.states.find(s=>s.id===f.get('stateId'));person.name=f.get('name').trim();person.stateId=f.get('stateId');person.active=state?.schedulable===true;person.typeIds=f.getAll('type');if(fresh)db.participants.push(person);db.participantResources=db.participantResources.filter(x=>x.participantId!==person.id);f.getAll('resource').forEach(resourceId=>db.participantResources.push({participantId:person.id,resourceId}));db.availabilities=db.availabilities.filter(a=>a.participantId!==person.id);f.getAll('slot').forEach(v=>{const [turnId,day]=v.split('|');db.availabilities.push({participantId:person.id,turnId,day:+day})});save(fresh?'Creación de participante':'Edición de participante',person.name);m.close();participants()})}
function sortParticipants(items){const {key,dir}=participantSort;return [...items].sort((a,b)=>{const av=key==='state'?stateFor(a)?.name:key==='assignments'?assignmentCount(a.id):key==='type'?(a.typeIds.map(id=>tagFor(id)?.name).join(' ')):a.name,bv=key==='state'?stateFor(b)?.name:key==='assignments'?assignmentCount(b.id):key==='type'?(b.typeIds.map(id=>tagFor(id)?.name).join(' ')):b.name;return (typeof av==='number'?av-bv:String(av).localeCompare(String(b),'es'))*(dir==='asc'?1:-1)})}
function legacyParticipants(){const shown=sortParticipants(db.participants.filter(p=>p.name.toLowerCase().includes(participantFilters.name.toLowerCase())&&(!participantFilters.type||p.typeIds.includes(participantFilters.type))&&(!participantFilters.state||p.stateId===participantFilters.state)&&String(assignmentCount(p.id)).includes(participantFilters.assignments)));const sortButton=(key,label)=>`<button class="sort-button" data-action="sortParticipants" data-key="${key}">${label}<span>${participantSort.key===key?(participantSort.dir==='asc'?'↑':'↓'):'↕'}</span></button>`;shell(`<div class="card"><div class="toolbar"><div><h2>Participantes</h2><p class="muted">Filtra u ordena la lista; selecciona un nombre para editarlo.</p></div><button class="primary" data-action="newParticipant">Agregar participante</button></div></div><div class="card"><div class="tablewrap"><table><thead><tr><th>${sortButton('name','Nombre')}</th><th>${sortButton('type','Etiquetas')}</th><th>${sortButton('state','Estado')}</th><th>${sortButton('assignments','Asignaciones')}</th><th>Acciones</th></tr><tr class="filter-row"><th><input data-filter="name" placeholder="Buscar nombre" value="${esc(participantFilters.name)}"></th><th><select data-filter="type"><option value="">Todas</option>${db.types.map(t=>`<option value="${t.id}" ${selected(participantFilters.type===t.id)}>${esc(t.name)}</option>`).join('')}</select></th><th><select data-filter="state"><option value="">Todos</option>${db.states.map(s=>`<option value="${s.id}" ${selected(participantFilters.state===s.id)}>${esc(s.name)}</option>`).join('')}</select></th><th><input data-filter="assignments" inputmode="numeric" placeholder="#" value="${esc(participantFilters.assignments)}"></th><th></th></tr></thead><tbody>${shown.length?shown.map(p=>{const state=stateFor(p);return `<tr><td><button class="participant-link" data-action="editParticipant" data-id="${p.id}" title="Editar ${esc(p.name)}"><span class="participant-avatar">${esc(p.name.trim().charAt(0).toUpperCase())}</span><span>${esc(p.name)}</span><span class="link-icon">✎</span></button></td><td><div class="tag-list">${p.typeIds.map(id=>{const t=tagFor(id);return t?`<span class="type-tag" style="--tag-color:${esc(t.color)}">${esc(t.name)}</span>`:''}).join('')||'—'}</div></td><td><span class="type-tag" style="--tag-color:${esc(state?.color||'#64748b')}">${esc(state?.name||'Sin estado')}</span></td><td>${assignmentCount(p.id)}</td><td><div class="row-actions"><button class="icon-button" title="Editar" aria-label="Editar ${esc(p.name)}" data-action="editParticipant" data-id="${p.id}">✎</button><button class="icon-button icon-danger" title="Eliminar" aria-label="Eliminar ${esc(p.name)}" data-action="deleteParticipant" data-id="${p.id}">⌫</button></div></td></tr>`}).join(''):`<tr><td colspan="5" class="empty">No se encontraron participantes.</td></tr>`}</tbody></table></div></div>`);document.querySelectorAll('[data-filter]').forEach(input=>input.addEventListener('input',e=>{participantFilters[e.target.dataset.filter]=e.target.value;participants()}))}
function typeDialog(t){modal(`<div class="toolbar"><h2>${t?'Editar':'Nueva'} etiqueta</h2><button type="button" data-close>Cerrar</button></div><div class="form"><label>Nombre<input name="name" required value="${esc(t?.name)}"></label><label>Color<input name="color" type="color" value="${esc(t?.color||typeColors[db.types.length%typeColors.length])}"></label></div><div class="modal-actions"><button type="button" data-close>Cancelar</button><button class="primary">Guardar</button></div>`,(f,m)=>{const name=f.get('name').trim();if(db.types.some(x=>x.id!==t?.id&&x.name.toLowerCase()===name.toLowerCase()))return formError('Ya existe una etiqueta con ese nombre.');if(t){t.name=name;t.color=f.get('color')}else db.types.push({id:uid(),name,color:f.get('color')});save(t?'Edición de etiqueta':'Creación de etiqueta',name);m.close();types()})}
function types(){shell(`<div class="card"><div class="toolbar"><div><h2>Etiquetas de participante</h2><p class="muted">Crea etiquetas de colores y asígnalas libremente a varios participantes.</p></div><button class="primary" data-action="newType">Agregar etiqueta</button></div></div><div class="card"><table><tr><th>Etiqueta</th><th>Participantes</th><th>Acciones</th></tr>${db.types.length?db.types.map(t=>`<tr><td><span class="type-tag" style="--tag-color:${esc(t.color)}">${esc(t.name)}</span></td><td>${db.participants.filter(p=>p.typeIds.includes(t.id)).length}</td><td><div class="row-actions"><button class="icon-button" title="Editar" aria-label="Editar ${esc(t.name)}" data-action="editType" data-id="${t.id}">✎</button><button class="icon-button icon-danger" title="Eliminar" aria-label="Eliminar ${esc(t.name)}" data-action="deleteType" data-id="${t.id}">⌫</button></div></td></tr>`).join(''):'<tr><td colspan="3" class="empty">No hay etiquetas definidas.</td></tr>'}</table></div>`)}
function stateDialog(state){modal(`<div class="toolbar"><h2>${state?'Editar':'Nuevo'} estado</h2><button type="button" data-close>Cerrar</button></div><div class="form"><label>Nombre<input name="name" required value="${esc(state?.name)}"></label><label>Color<input name="color" type="color" value="${esc(state?.color||stateColors[db.states.length%stateColors.length])}"></label><label class="state-rule"><input name="schedulable" type="checkbox" ${checked(state?.schedulable)}><span>Puede participar en el programa</span></label></div><div class="modal-actions"><button type="button" data-close>Cancelar</button><button class="primary">Guardar</button></div>`,(f,m)=>{const name=f.get('name').trim();if(db.states.some(s=>s.id!==state?.id&&s.name.toLowerCase()===name.toLowerCase()))return formError('Ya existe un estado con ese nombre.');const item=state||{id:uid()};item.name=name;item.color=f.get('color');item.schedulable=f.get('schedulable')==='on';if(!state)db.states.push(item);db.participants.filter(p=>p.stateId===item.id).forEach(p=>p.active=item.schedulable);save(state?'Edición de estado':'Creación de estado',item.name);m.close();states()})}
function states(){shell(`<div class="card"><div class="toolbar"><div><h2>Estados de participante</h2><p class="muted">Define tus estados y si permiten que la persona participe en el programa.</p></div><button class="primary" data-action="newState">Agregar estado</button></div></div><div class="card"><table><tr><th>Estado</th><th>Participa</th><th>Participantes</th><th>Acciones</th></tr>${db.states.map(s=>`<tr><td><span class="type-tag" style="--tag-color:${esc(s.color)}">${esc(s.name)}</span></td><td>${s.schedulable?'Sí':'No'}</td><td>${db.participants.filter(p=>p.stateId===s.id).length}</td><td><div class="row-actions"><button class="icon-button" title="Editar" aria-label="Editar ${esc(s.name)}" data-action="editState" data-id="${s.id}">✎</button><button class="icon-button icon-danger" title="Eliminar" aria-label="Eliminar ${esc(s.name)}" data-action="deleteState" data-id="${s.id}">⌫</button></div></td></tr>`).join('')}</table></div>`)}
function turnDialog(t){const useDays=t?.days??[0,1,2,3,4,5,6];modal(`<div class="toolbar"><h2>${t?'Editar':'Nuevo'} turno</h2><button type="button" data-close>Cerrar</button></div><div class="form"><label>Nombre<input name="name" required value="${esc(t?.name)}"></label><label>Hora inicial<input name="start" type="time" required value="${t?.start||'08:00'}"></label><label>Hora final<input name="end" type="time" required value="${t?.end||'11:00'}"></label><label>Estado<select name="active"><option value="true" ${selected(t?.active!==false)}>Activo</option><option value="false" ${selected(t?.active===false)}>Inactivo</option></select></label></div><h3>Días permitidos</h3><div class="checkgrid">${days.map((d,i)=>`<label><input type="checkbox" name="day" value="${i}" ${checked(useDays.includes(i))}>${d}</label>`).join('')}</div><div class="modal-actions"><button type="button" data-close>Cancelar</button><button class="primary">Guardar</button></div>`,(f,m)=>{const fresh=!t;const item=t||{id:uid()};item.name=f.get('name').trim();item.start=f.get('start');item.end=f.get('end');item.active=f.get('active')==='true';item.days=f.getAll('day').map(Number);if(item.start>=item.end)return formError('La hora final debe ser posterior a la inicial.');if(fresh)db.turns.push(item);save(fresh?'Creación de turno':'Edición de turno',item.name);m.close();turns()})}
function turns(){shell(`<div class="card"><div class="toolbar"><div><h2>Turnos</h2><p class="muted">El turno inicial “Mañana” puede editarse o eliminarse.</p></div><button class="primary" data-action="newTurn">Agregar turno</button></div></div><div class="card"><div class="tablewrap"><table><tr><th>Turno</th><th>Horario</th><th>Días</th><th>Estado</th><th>Acciones</th></tr>${db.turns.map(t=>`<tr><td>${esc(t.name)}</td><td>${t.start}–${t.end}</td><td>${t.days.map(x=>days[x]).join(', ')}</td><td><span class="status ${t.active?'status-active':'status-inactive'}">${t.active?'Activo':'Inactivo'}</span></td><td><div class="row-actions"><button class="icon-button" title="Editar" aria-label="Editar ${esc(t.name)}" data-action="editTurn" data-id="${t.id}">✎</button><button class="icon-button" title="${t.active?'Desactivar':'Activar'}" aria-label="${t.active?'Desactivar':'Activar'} ${esc(t.name)}" data-action="toggleTurn" data-id="${t.id}">${t.active?'◐':'◑'}</button><button class="icon-button icon-danger" title="Eliminar" aria-label="Eliminar ${esc(t.name)}" data-action="deleteTurn" data-id="${t.id}">⌫</button></div></td></tr>`).join('')}</table></div></div>`)}
function resourceDialog(r){const minimum=minimumForResource(r),maximum=maximumForResource(r);modal(`<div class="toolbar"><h2>${r?'Editar':'Nuevo'} punto</h2><button type="button" data-close>Cerrar</button></div><div class="form"><label>Nombre<input name="name" required value="${esc(r?.name)}"></label><label>Ubicación<input name="location" value="${esc(r?.location)}"></label><label>Participantes mínimos<input name="minParticipants" type="number" min="1" max="50" step="1" required value="${minimum}"></label><label>Participantes máximos<input name="maxParticipants" type="number" min="1" max="50" step="1" required value="${maximum}"></label><label>Estado<select name="active"><option value="true" ${selected(r?.active!==false)}>Activo</option><option value="false" ${selected(r?.active===false)}>Inactivo</option></select></label></div><div class="modal-actions"><button type="button" data-close>Cancelar</button><button class="primary">Guardar</button></div>`,(f,m)=>{const min=Math.max(1,Math.min(50,Math.floor(Number(f.get('minParticipants'))||1))),max=Math.max(1,Math.min(50,Math.floor(Number(f.get('maxParticipants'))||1)));if(max<min)return formError('El máximo debe ser igual o mayor que el mínimo.');const fresh=!r;const item=r||{id:uid()};item.name=f.get('name').trim();item.location=f.get('location').trim();item.minParticipants=min;item.maxParticipants=max;item.active=f.get('active')==='true';if(fresh)db.resources.push(item);save(fresh?'Creación de punto':'Edición de punto',item.name);m.close();resources()})}
function resources(){shell(`<div class="card"><div class="toolbar"><div><h2>Puntos</h2><p class="muted">Define el mínimo y máximo recomendado de participantes por punto.</p></div><button class="primary" data-action="newResource">Agregar punto</button></div></div><div class="card"><div class="tablewrap"><table><tr><th>Nombre</th><th>Ubicación</th><th>Participantes mínimos</th><th>Participantes máximos</th><th>Estado</th><th>Acciones</th></tr>${db.resources.map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.location)}</td><td>${minimumForResource(r)}</td><td>${maximumForResource(r)}</td><td><span class="status ${r.active?'status-active':'status-inactive'}">${r.active?'Activo':'Inactivo'}</span></td><td><div class="row-actions"><button class="icon-button" title="Editar" aria-label="Editar ${esc(r.name)}" data-action="editResource" data-id="${r.id}">✎</button><button class="icon-button" title="${r.active?'Desactivar':'Activar'}" aria-label="${r.active?'Desactivar':'Activar'} ${esc(r.name)}" data-action="toggleResource" data-id="${r.id}">${r.active?'◐':'◑'}</button><button class="icon-button icon-danger" title="Eliminar" aria-label="Eliminar ${esc(r.name)}" data-action="deleteResource" data-id="${r.id}">⌫</button></div></td></tr>`).join('')}</table></div></div>`)}
function availability(){const p=db.participants.find(x=>x.id===availabilityId)||db.participants[0],turns=db.turns.filter(x=>x.active);shell(`<div class="card"><h2>Disponibilidad</h2><p class="muted">También puede editarse al abrir la ficha de un participante.</p>${p?`<form id="availabilityForm"><label>Participante<select id="availabilityParticipant">${db.participants.map(x=>`<option value="${x.id}" ${selected(x.id===p.id)}>${esc(x.name)}${x.active?'':' (inactivo)'}</option>`).join('')}</select></label><div class="checkgrid">${turns.flatMap(t=>days.map((d,i)=>`<label><input type="checkbox" name="slot" value="${t.id}|${i}" ${checked(db.availabilities.some(a=>a.participantId===p.id&&a.turnId===t.id&&a.day===i))}>${d} · ${esc(t.name)}</label>`)).join('')}</div><div class="modal-actions"><button type="button" data-action="clearAvailability" data-id="${p.id}">Eliminar disponibilidad</button><button class="primary">Guardar disponibilidad</button></div></form>`:'<p class="empty">Crea un participante para registrar disponibilidad.</p>'}</div>`);document.querySelector('#availabilityParticipant')?.addEventListener('change',e=>{availabilityId=e.target.value;availability()});document.querySelector('#availabilityForm')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);db.availabilities=db.availabilities.filter(a=>a.participantId!==p.id);f.getAll('slot').forEach(v=>{const [turnId,day]=v.split('|');db.availabilities.push({participantId:p.id,turnId,day:+day})});save('Actualización de disponibilidad',p.name);availability()})}
const iso=d=>d.toISOString().slice(0,10),assignmentCount=id=>db.programs.flatMap(p=>p.assignments).filter(a=>a.participantIds.includes(id)).length,timeOverlap=(a,b)=>a&&b&&a.start<b.end&&b.start<a.end;
const resourceAvailable=(participantId,resourceId)=>db.participantResources.some(x=>x.participantId===participantId&&x.resourceId===resourceId);
const availableForAssignment=(participantId,assignment,program)=>{const turn=db.turns.find(item=>item.id===assignment.turnId),day=new Date(`${assignment.date}T12:00:00`).getDay();if(!turn||!resourceAvailable(participantId,assignment.resourceId)||!db.availabilities.some(item=>item.participantId===participantId&&item.turnId===turn.id&&item.day===day))return false;return !program.assignments.some(other=>other.id!==assignment.id&&other.date===assignment.date&&other.participantIds.includes(participantId)&&timeOverlap(db.turns.find(item=>item.id===other.turnId),turn))};
