document.querySelectorAll('#nav button[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;document.querySelectorAll('#nav button[data-view]').forEach(x=>x.classList.toggle('active',x===b));render()});document.querySelector('#backupBtn').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}));a.download=`respaldo-predicacion-${now().slice(0,10)}.json`;a.click();save('Creación de respaldo','Manual')};document.querySelector('#restoreInput').onchange=e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{db=JSON.parse(r.result);for(const key of ['types','states','logs','availabilities','participantResources','programs'])db[key]??=[];if(!db.states.length)db.states=[{id:'state-active',name:'Activo',color:'#15803d',schedulable:true},{id:'state-inactive',name:'Inactivo',color:'#64748b',schedulable:false}];db.types.forEach((type,index)=>type.color??=typeColors[index%typeColors.length]);db.states.forEach((state,index)=>{state.color??=stateColors[index%stateColors.length];state.schedulable??=false});db.participants.forEach(person=>{person.typeIds??=(person.typeId?[person.typeId]:[]);person.stateId??=(person.active===false?'state-inactive':'state-active')});save('Restauración de respaldo',f.name);render()}catch{noticeDialog({title:'No se pudo importar el respaldo',message:'El archivo seleccionado no es un respaldo válido.'})}};r.readAsText(f)};
const toggleMenu=(toggleId,menuId)=>{const menu=document.querySelector(menuId),toggle=document.querySelector(toggleId);menu.hidden=!menu.hidden;toggle.setAttribute('aria-expanded',String(!menu.hidden));toggle.querySelector('b').textContent=menu.hidden?'›':'⌄'};
