if(initialConfigMenu&&initialConfigToggle){initialConfigMenu.hidden=true;initialConfigToggle.setAttribute('aria-expanded','false');initialConfigToggle.querySelector('b').textContent='›'}
document.querySelector('#configToggle').onclick=()=>{if(document.querySelector('.sidebar').classList.contains('collapsed')){document.querySelector('#sidebarCollapse').click();if(document.querySelector('#configMenu').hidden)toggleMenu('#configToggle','#configMenu');return}toggleMenu('#configToggle','#configMenu')};
document.querySelector('#systemToggle')?.addEventListener('click',()=>toggleMenu('#systemToggle','#systemMenu'));
function programs(){shell(`<div class="card"><div class="toolbar"><div><h2>Programas</h2><p class="muted">Crea, consulta y exporta tus programas mensuales.</p></div><button class="primary" data-action="newProgram">Crear programa</button></div></div><div class="card"><h3>Programas existentes</h3>${db.programs.length?`<div class="tablewrap"><table><tr><th>Programa</th><th>Estado</th><th>Actualizado</th><th class="program-actions-header">Acciones</th></tr>${db.programs.map(p=>`<tr><td><button class="program-link" data-action="openProgram" data-id="${p.id}" title="Editar programa ${esc(formatMonth(p.month))}">${esc(formatMonth(p.month))}</button></td><td>${esc(p.status)}</td><td>${new Date(p.updatedAt).toLocaleString()}</td><td class="program-actions"><div class="row-actions"><button class="icon-button" title="Abrir programa" aria-label="Abrir programa ${esc(formatMonth(p.month))}" data-action="openProgram" data-id="${p.id}">↗</button><button class="icon-button" title="Exportar CSV" aria-label="Exportar CSV ${esc(formatMonth(p.month))}" data-action="export" data-id="${p.id}">↓</button><button class="icon-button icon-danger" title="Eliminar programa" aria-label="Eliminar programa ${esc(formatMonth(p.month))}" data-action="deleteProgram" data-id="${p.id}">⌫</button></div></td></tr>`).join('')}</table></div>`:'<p class="empty">Aún no hay programas. Crea el primero para comenzar.</p>'}</div>`)}
function participantActivityMarkup(person){
 if(!person)return '<p class="muted">La actividad aparecerá cuando el participante tenga asignaciones en un programa.</p>';
 const rows=db.programs.map(program=>{const assignments=program.assignments.filter(assignment=>assignment.participantIds.includes(person.id));return {program,assignments}}).filter(row=>row.assignments.length);
 const total=rows.reduce((sum,row)=>sum+row.assignments.length,0);
 return `<div class="activity-metrics"><div><strong>${total}</strong><span>asignaciones históricas</span></div><div><strong>${rows.length}</strong><span>programas con actividad</span></div></div><label class="activity-filter">Filtrar por programa<select data-activity-filter><option value="">Todos los programas</option>${rows.map(({program})=>`<option value="${program.id}">${esc(program.month)} · ${esc(program.status)}</option>`).join('')}</select></label><div class="activity-list">${rows.length?rows.map(({program,assignments})=>{const points=[...new Set(assignments.map(assignment=>db.resources.find(resource=>resource.id===assignment.resourceId)?.name).filter(Boolean))],turnsUsed=[...new Set(assignments.map(assignment=>db.turns.find(turn=>turn.id===assignment.turnId)?.name).filter(Boolean))];return `<article class="activity-row" data-activity-program="${program.id}"><div><strong>${esc(program.month)}</strong><span class="tag">${esc(program.status)}</span></div><b>${assignments.length} asignación${assignments.length===1?'':'es'}</b><small>${esc(points.join(' · ')||'Sin punto')} · ${esc(turnsUsed.join(' · ')||'Sin turno')}</small></article>`}).join(''):'<p class="muted">Todavía no hay actividad registrada en programas.</p>'}</div>`
}
function participantDialog(p){
 const slots=p?db.availabilities.filter(item=>item.participantId===p.id):[],resourceIds=p?db.participantResources.filter(item=>item.participantId===p.id).map(item=>item.resourceId):[],typeIds=p?.typeIds??[],currentState=stateFor(p||{});
 modal(`<div class="toolbar"><div><span class="eyebrow">Ficha de participante</span><h2>${p?'Editar':'Nuevo'} participante</h2></div><button type="button" class="icon-button" title="Cerrar" aria-label="Cerrar" data-close>×</button></div><div class="participant-tabs" role="tablist"><button type="button" class="active" role="tab" aria-selected="true" data-participant-tab="details">Información y disponibilidad</button><button type="button" role="tab" aria-selected="false" data-participant-tab="activity">Actividad${p?'':''}</button></div><section data-participant-panel="details"><div class="form"><label>Nombre<input name="name" required value="${esc(p?.name)}"></label><label>Estado<select name="stateId">${db.states.map(state=>`<option value="${state.id}" ${selected(currentState?.id===state.id)}>${esc(state.name)}</option>`).join('')}</select></label></div><div class="availability-heading"><div><h3>Roles</h3></div><p class="muted small">Puedes asignar uno o varios roles.</p></div><div class="type-options">${db.types.map(type=>`<label class="type-option" style="--tag-color:${esc(type.color)}"><input type="checkbox" name="type" value="${type.id}" ${checked(typeIds.includes(type.id))}><span>${esc(type.name)}</span></label>`).join('')||'<p class="muted">Crea roles para poder asignarlos.</p>'}</div><div class="availability-heading"><div><h3>Lugares asignables</h3></div><p class="muted small">Selecciona los puntos en los que esta persona puede participar.</p></div><div class="resource-options">${db.resources.filter(resource=>resource.active).map(resource=>`<label class="resource-option"><input type="checkbox" name="resource" value="${resource.id}" ${checked(resourceIds.includes(resource.id))}><span class="resource-marker">⌖</span><span><strong>${esc(resource.name)}</strong></span></label>`).join('')||'<p class="muted">No hay puntos activos.</p>'}</div><div class="availability-heading"><div><span class="eyebrow">Calendario semanal</span><h3>Disponibilidad de horarios</h3></div><p class="muted small">Marca únicamente los días disponibles.</p></div><div class="availability-grid">${db.turns.filter(turn=>turn.active).map(turn=>`<section class="turn-card"><div class="turn-card-title"><span class="turn-icon">◷</span><div><strong>${esc(turn.name)}</strong><small>${turn.start} – ${turn.end}</small></div></div><div class="day-options">${days.map((day,index)=>`<label class="day-option"><input type="checkbox" name="slot" value="${turn.id}|${index}" ${checked(slots.some(slot=>slot.turnId===turn.id&&slot.day===index))}><span>${day}</span></label>`).join('')}</div></section>`).join('')}</div></section><section data-participant-panel="activity" hidden><div class="availability-heading"><div><span class="eyebrow">Historial</span><h3>Actividad en programas</h3></div><p class="muted small">Consulta la carga acumulada y filtra un programa específico.</p></div>${participantActivityMarkup(p)}</section><div class="modal-actions"><button type="button" data-close>Cancelar</button><button class="primary">Guardar</button></div>`,(form,dialog)=>{const fresh=!p,person=p||{id:uid()},state=db.states.find(item=>item.id===form.get('stateId'));person.name=form.get('name').trim();person.stateId=form.get('stateId');person.active=state?.schedulable===true;person.typeIds=form.getAll('type');if(fresh)db.participants.push(person);db.participantResources=db.participantResources.filter(item=>item.participantId!==person.id);form.getAll('resource').forEach(resourceId=>db.participantResources.push({participantId:person.id,resourceId}));db.availabilities=db.availabilities.filter(item=>item.participantId!==person.id);form.getAll('slot').forEach(value=>{const [turnId,day]=value.split('|');db.availabilities.push({participantId:person.id,turnId,day:+day})});save(fresh?'Creación de participante':'Edición de participante',person.name);dialog.close();participants()})
}
function participants(){
 const shown=sortParticipants(db.participants.filter(person=>person.name.toLowerCase().includes(participantFilters.name.toLowerCase())&&(!participantFilters.type||person.typeIds.includes(participantFilters.type))&&(!participantFilters.state||person.stateId===participantFilters.state)));
 const sortButton=(key,label)=>`<button class="sort-button" data-action="sortParticipants" data-key="${key}">${label}<span>${participantSort.key===key?(participantSort.dir==='asc'?'↑':'↓'):'↕'}</span></button>`;
 document.querySelectorAll('[data-filter]').forEach(input=>input.addEventListener('input',event=>{participantFilters[event.target.dataset.filter]=event.target.value;participants()}))
}
document.addEventListener('click',event=>{const tab=event.target.closest('[data-participant-tab]');if(!tab)return;const modalRoot=document.querySelector('#modal');modalRoot.querySelectorAll('[data-participant-tab]').forEach(button=>{const active=button===tab;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active))});modalRoot.querySelectorAll('[data-participant-panel]').forEach(panel=>panel.hidden=panel.dataset.participantPanel!==tab.dataset.participantTab)});
document.addEventListener('change',event=>{if(!event.target.matches('[data-activity-filter]'))return;const programId=event.target.value;document.querySelectorAll('[data-activity-row]').forEach(row=>row.hidden=!!programId&&row.dataset.activityProgram!==programId)});
const spouseFor=person=>person?.spouseId?db.participants.find(candidate=>candidate.id===person.spouseId):undefined;
const genderClass=person=>person?.gender==='Hombre'?'gender-masculine':person?.gender==='Mujer'?'gender-feminine':'';
const genderMark=person=>person?.gender?`<span class="gender-mark ${genderClass(person)}" title="${esc(person.gender)}" aria-label="${esc(person.gender)}">${person.gender==='Hombre'?'♂':'♀'}</span>`:'';
const spouseMark=person=>{const spouse=spouseFor(person);return spouse?`<span class="spouse-mark" title="Cónyuge: ${esc(spouse.name)}" aria-label="Cónyuge: ${esc(spouse.name)}">👫</span>`:''};
const participantAvatar=person=>`<span class="participant-avatar ${genderClass(person)}" title="${person?.gender?esc(person.gender):'Género sin especificar'}">${esc(person?.name?.trim().charAt(0).toUpperCase()||'?')}</span>`;
const participantLabel=person=>`${esc(person.name)}${genderMark(person)}${spouseMark(person)}`;
function spouseOptions(person,gender,currentId){const candidates=db.participants.filter(candidate=>candidate.id!==person?.id&&candidate.gender&&candidate.gender!==gender&&(!candidate.spouseId||candidate.spouseId===person?.id)).sort((a,b)=>a.name.localeCompare(b.name,'es'));if(!gender)return '<option value="">Selecciona primero el género</option>';return `<option value="">Sin cónyuge asignado</option>${candidates.map(candidate=>`<option value="${candidate.id}" ${selected(candidate.id===currentId)}>${esc(candidate.name)}${candidate.active?'':' (inactivo)'}</option>`).join('')||'<option value="" disabled>No hay participantes compatibles</option>'}`}
function spouseLinkError(person,gender,spouseId){if(!spouseId)return '';const spouse=db.participants.find(candidate=>candidate.id===spouseId);if(!spouse||spouse.id===person.id)return 'Selecciona un cónyuge válido.';if(!genders.includes(gender)||!genders.includes(spouse.gender)||gender===spouse.gender)return 'El cónyuge debe ser un participante del género opuesto.';if(spouse.spouseId&&spouse.spouseId!==person.id)return `${spouse.name} ya tiene un cónyuge asignado.`;return ''}
function setSpouseLink(person,spouseId){const former=spouseFor(person);if(former?.spouseId===person.id)former.spouseId='';person.spouseId='';if(!spouseId)return;const spouse=db.participants.find(candidate=>candidate.id===spouseId);if(!spouse)return;const spouseFormer=spouseFor(spouse);if(spouseFormer?.spouseId===spouse.id)spouseFormer.spouseId='';person.spouseId=spouse.id;spouse.spouseId=person.id}
function setupSpouseSelector(person){const dialog=document.querySelector('#modal'),gender=dialog?.querySelector('[name="gender"]'),spouse=dialog?.querySelector('[name="spouseId"]');if(!gender||!spouse)return;const refresh=()=>{const current=spouse.value;spouse.innerHTML=spouseOptions(person,gender.value,current);spouse.disabled=!gender.value;if(current&&[...spouse.options].some(option=>option.value===current))spouse.value=current};gender.addEventListener('change',refresh);refresh()}
const participantDialogBeforeGender=participantDialog;
participantDialog=function(p){participantDialogBeforeGender(p);const dialog=document.querySelector('#modal'),fields=dialog.querySelector('[data-participant-panel="details"] .form'),form=dialog.querySelector('#modalForm'),currentGender=p?.gender||'',currentSpouse=p?.spouseId||'';fields.insertAdjacentHTML('beforeend',`<label>Género<select name="gender" required><option value="" ${selected(!currentGender)} disabled>Selecciona una opción</option>${genders.map(gender=>`<option value="${gender}" ${selected(currentGender===gender)}>${gender}</option>`).join('')}</select></label><label>Cónyuge<select name="spouseId" ${currentGender?'':'disabled'}>${spouseOptions(p,currentGender,currentSpouse)}</select><small class="field-help">Solo se muestran participantes del género opuesto sin otra relación.</small></label>`);setupSpouseSelector(p);form.onsubmit=event=>{event.preventDefault();const data=new FormData(form),fresh=!p,person=p||{id:uid(),spouseId:''},state=db.states.find(item=>item.id===data.get('stateId')),gender=data.get('gender'),spouseId=data.get('spouseId');if(!genders.includes(gender))return formError('Selecciona el género del participante.');const linkError=spouseLinkError(person,gender,spouseId);if(linkError)return formError(linkError);person.name=data.get('name').trim();person.stateId=data.get('stateId');person.active=state?.schedulable===true;person.gender=gender;person.typeIds=data.getAll('type');if(fresh)db.participants.push(person);setSpouseLink(person,spouseId);db.participantResources=db.participantResources.filter(item=>item.participantId!==person.id);data.getAll('resource').forEach(resourceId=>db.participantResources.push({participantId:person.id,resourceId}));db.availabilities=db.availabilities.filter(item=>item.participantId!==person.id);data.getAll('slot').forEach(value=>{const [turnId,day]=value.split('|');db.availabilities.push({participantId:person.id,turnId,day:+day})});person.frequencyCount=Math.max(1,Math.min(52,Math.floor(Number(data.get('frequencyCount'))||1)));person.frequencyWeeks=Math.max(1,Math.min(52,Math.floor(Number(data.get('frequencyWeeks'))||1)));save(fresh?'Creación de participante':'Edición de participante',person.name);dialog.close();participants()}}
const participantsBeforeGender=participants;
participants=function(){const shown=sortParticipants(db.participants.filter(person=>person.name.toLowerCase().includes(participantFilters.name.toLowerCase())&&(!participantFilters.type||person.typeIds.includes(participantFilters.type))&&(!participantFilters.state||person.stateId===participantFilters.state)&&(!participantFilters.gender||person.gender===participantFilters.gender)&&(!participantFilters.spouse||(participantFilters.spouse==='with'?!!spouseFor(person):!spouseFor(person)))));const sortButton=(key,label)=>`<button class="sort-button" data-action="sortParticipants" data-key="${key}">${label}<span>${participantSort.key===key?(participantSort.dir==='asc'?'↑':'↓'):'↕'}</span></button>`;shell(`<div class="card"><div class="toolbar"><div><h2>Participantes</h2><p class="muted">Filtra u ordena la lista; selecciona un nombre para editarlo.</p></div><button class="primary" data-action="newParticipant">Agregar participante</button></div></div><div class="card"><div class="tablewrap"><table><thead><tr><th>${sortButton('name','Nombre')}</th><th>${sortButton('type','Roles')}</th><th>${sortButton('state','Estado')}</th><th>Acciones</th></tr><tr class="filter-row"><th><input data-filter="name" placeholder="Buscar nombre" value="${esc(participantFilters.name)}"></th><th><select data-filter="type"><option value="">Todos</option>${db.types.map(type=>`<option value="${type.id}" ${selected(participantFilters.type===type.id)}>${esc(type.name)}</option>`).join('')}</select></th><th><select data-filter="state"><option value="">Todos</option>${db.states.map(state=>`<option value="${state.id}" ${selected(participantFilters.state===state.id)}>${esc(state.name)}</option>`).join('')}</select></th><th><div class="participant-extra-filters"><select data-filter="gender" aria-label="Filtrar por género"><option value="">Todos los géneros</option>${genders.map(gender=>`<option value="${gender}" ${selected(participantFilters.gender===gender)}>${gender}</option>`).join('')}</select><select data-filter="spouse" aria-label="Filtrar por cónyuge"><option value="">Con o sin cónyuge</option><option value="with" ${selected(participantFilters.spouse==='with')}>Con cónyuge</option><option value="without" ${selected(participantFilters.spouse==='without')}>Sin cónyuge</option></select></div></th></tr></thead><tbody>${shown.length?shown.map(person=>{const state=stateFor(person);return `<tr><td><button class="participant-link" data-action="editParticipant" data-id="${person.id}" title="Editar ${esc(person.name)}">${participantAvatar(person)}<span>${participantLabel(person)}</span><span class="link-icon">✎</span></button></td><td><div class="tag-list">${person.typeIds.map(id=>{const type=tagFor(id);return type?`<span class="type-tag" style="--tag-color:${esc(type.color)}">${esc(type.name)}</span>`:''}).join('')||'—'}</div></td><td><span class="type-tag" style="--tag-color:${esc(state?.color||'#64748b')}">${esc(state?.name||'Sin estado')}</span></td><td><div class="row-actions"><button class="icon-button" title="Editar" aria-label="Editar ${esc(person.name)}" data-action="editParticipant" data-id="${person.id}">✎</button><button class="icon-button icon-danger" title="Eliminar" aria-label="Eliminar ${esc(person.name)}" data-action="deleteParticipant" data-id="${person.id}">⌫</button></div></td></tr>`}).join(''):`<tr><td colspan="4" class="empty">No se encontraron participantes.</td></tr>`}</tbody></table></div></div>`);document.querySelectorAll('[data-filter]').forEach(input=>input.addEventListener('change',event=>{participantFilters[event.target.dataset.filter]=event.target.value;participants()}))}
generate=function(month){const [year,monthNumber]=month.split('-').map(Number),out=[],eligible=(person,resource,turn,day)=>person?.active&&resourceAvailable(person.id,resource.id)&&db.availabilities.some(slot=>slot.participantId===person.id&&slot.turnId===turn.id&&slot.day===day),blocked=(personId,date,turn)=>out.some(assignment=>assignment.date===date&&assignment.participantIds.includes(personId)&&timeOverlap(db.turns.find(candidate=>candidate.id===assignment.turnId),turn));for(const dateValue=new Date(year,monthNumber-1,1);dateValue.getMonth()===monthNumber-1;dateValue.setDate(dateValue.getDate()+1)){const day=dateValue.getDay(),date=iso(dateValue);for(const turn of db.turns.filter(item=>item.active&&item.days.includes(day)))for(const resource of db.resources.filter(item=>item.active)){const minimum=minimumForResource(resource),ids=[],candidates=db.participants.filter(person=>eligible(person,resource,turn,day)).sort((a,b)=>assignmentCount(a.id)-assignmentCount(b.id));for(const person of candidates){if(ids.length>=minimum||ids.includes(person.id)||blocked(person.id,date,turn))continue;const spouse=spouseFor(person),together=spouse?.active&&eligible(spouse,resource,turn,day)&&!ids.includes(spouse.id)&&!blocked(spouse.id,date,turn);if(together)ids.push(person.id,spouse.id);else ids.push(person.id)}out.push({id:uid(),date,turnId:turn.id,resourceId:resource.id,participantIds:ids,origin:'automática',protected:false})}}return out}
const legacyValidate=validate;
validate=function(program){const result=legacyValidate(program);for(const assignment of program.assignments){const resource=db.resources.find(item=>item.id===assignment.resourceId),maximum=maximumForResource(resource);if(assignment.participantIds.length>maximum)result.push(`${assignment.date}: ${resource?.name||'El punto'} supera el máximo de ${maximum} participante(s)`)}return [...new Set(result)]}
exportCsv=function(id){const program=db.programs.find(item=>item.id===id),rows=[['Fecha','Turno','Punto','Mínimo','Máximo','Participantes','Géneros','Origen','Validación']];program.assignments.forEach(assignment=>{const resource=db.resources.find(item=>item.id===assignment.resourceId),minimum=minimumForResource(resource),maximum=maximumForResource(resource),people=assignment.participantIds.map(personId=>db.participants.find(item=>item.id===personId)).filter(Boolean),validation=people.length<minimum?'Incompleta':people.length>maximum?'Sobrecupo':'OK';rows.push([assignment.date,db.turns.find(item=>item.id===assignment.turnId)?.name,resource?.name,minimum,maximum,people.map(person=>person.name).join(' | '),people.map(person=>person.gender||'Sin especificar').join(' | '),assignment.origin,validation])});const blob=new Blob([rows.map(row=>row.map(value=>`"${String(value??'').replaceAll('"','""')}"`).join(',')).join('\n')],{type:'text/csv'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`programa-${program.month}.csv`;link.click();URL.revokeObjectURL(url)}
