const creationModeCopy={blank:{title:'En blanco',description:'Crea los turnos y puntos activos sin participantes asignados.'},auto:{title:'Autoasignar',description:'Propone participantes de acuerdo con disponibilidad y reglas actuales.'},copy:{title:'Basado en otro programa',description:'Repite la distribución por día de semana y posición dentro del mes.'}};

newProgram=function(){const defaultMonth=new Date().toISOString().slice(0,7),sources=[...db.programs],defaultSource=sources[0]?.id||'',sourceOptions=sources.map(program=>`<option value="${program.id}">${esc(formatMonth(program.month))} · creado ${esc(formatDateTime(program.createdAt||program.updatedAt))}</option>`).join('');shell(`<section class="card new-program-wizard"><div><span class="eyebrow">Nuevo programa mensual</span><h2>¿Cómo quieres iniciar el programa?</h2><p class="muted">Elige un punto de partida; siempre podrás ajustar las asignaciones después.</p></div><form id="monthForm" class="creation-form"><div class="creation-methods" role="group" aria-label="Método de creación"><button type="button" class="creation-option" data-creation-mode="blank" aria-pressed="false"><span class="creation-option-icon" aria-hidden="true">□</span><strong>En blanco</strong><small>Turnos y puntos listos para asignar manualmente.</small></button><button type="button" class="creation-option is-selected" data-creation-mode="auto" aria-pressed="true"><span class="creation-option-icon" aria-hidden="true">✦</span><strong>Autoasignar</strong><small>Usa la disponibilidad y las reglas actuales.</small></button><button type="button" class="creation-option" data-creation-mode="copy" aria-pressed="false" ${sources.length?'':'disabled'}><span class="creation-option-icon" aria-hidden="true">⧉</span><strong>Usar otro programa</strong><small>${sources.length?'Copia la distribución semanal de un programa existente.':'Crea primero un programa para usar esta opción.'}</small></button></div><div class="creation-controls"><label>Mes<input name="month" type="month" value="${defaultMonth}" required></label><label class="creation-source" hidden>Programa de origen<select name="sourceProgram">${sourceOptions}</select></label></div><section class="creation-preview" aria-live="polite"></section><p class="creation-inline-error" hidden></p><div class="modal-actions creation-actions"><button class="primary" type="submit">Crear programa</button></div></form></section>`);const form=document.querySelector('#monthForm'),monthInput=form.elements.month,sourceInput=form.elements.sourceProgram,sourceField=form.querySelector('.creation-source'),preview=form.querySelector('.creation-preview'),error=form.querySelector('.creation-inline-error');let mode='auto';const updatePreview=()=>{const month=monthInput.value||defaultMonth,sourceId=sourceInput.value,assignments=draftAssignmentsForProgram(month,mode,sourceId),draft={month,assignments},groups=classifyProgramAssignments(draft),source=mode==='copy'?db.programs.find(program=>program.id===sourceId):null,copyDetail=source?` · Origen: ${formatMonth(source.month)}`:'';preview.innerHTML=`<div><span class="eyebrow">Vista previa</span><strong>${creationModeCopy[mode].title}${esc(copyDetail)}</strong><small>${creationModeCopy[mode].description}</small></div><div class="creation-preview-metrics"><span><b>${assignments.length}</b> asignaciones</span><span><b>${groups.complete.length}</b> completas</span><span><b>${groups.pending.length}</b> pendientes</span><span><b>${groups.warning.length}</b> advertencias</span></div>`};const chooseMode=nextMode=>{mode=nextMode;form.querySelectorAll('[data-creation-mode]').forEach(option=>{const selected=option.dataset.creationMode===mode;option.classList.toggle('is-selected',selected);option.setAttribute('aria-pressed',String(selected))});sourceField.hidden=mode!=='copy';error.hidden=true;updatePreview()};form.querySelectorAll('[data-creation-mode]').forEach(option=>option.onclick=()=>chooseMode(option.dataset.creationMode));monthInput.onchange=updatePreview;sourceInput.onchange=updatePreview;form.onsubmit=event=>{event.preventDefault();const month=monthInput.value,sourceId=sourceInput.value;if(mode==='copy'&&!sourceId){error.textContent='Selecciona el programa que quieres usar como base.';error.hidden=false;return}const source=mode==='copy'?db.programs.find(program=>program.id===sourceId):null,createdAt=now(),program={id:uid(),month,createdAt,updatedAt:createdAt,status:'Borrador',assignments:draftAssignmentsForProgram(month,mode,sourceId),creationMode:mode,sourceProgramId:source?.id||''};db.programs.unshift(program);programScope='all';save('Creación de programa',mode==='copy'?`${formatMonth(month)} basado en ${formatMonth(source.month)}`:`${formatMonth(month)} · ${creationModeCopy[mode].title}`);openProgram(program.id)};updatePreview()};

const originalShell=shell;
shell=function(html){originalShell(html);document.querySelectorAll('table').forEach(table=>{const programButton=table.querySelector('button[data-action="openProgram"]');if(!programButton||table.querySelector('.program-created-header'))return;const header=table.rows[0],updatedHeader=[...header.cells].find(cell=>cell.textContent.trim()==='Actualizado');if(!updatedHeader)return;const createdHeader=document.createElement('th');createdHeader.className='program-created-header';createdHeader.textContent='Creado';updatedHeader.before(createdHeader);[...table.rows].slice(1).forEach(row=>{const button=row.querySelector('button[data-action="openProgram"]'),program=db.programs.find(item=>item.id===button?.dataset.id);if(!program)return;const updatedCell=[...row.cells].find(cell=>cell.textContent.trim()&&cell.nextElementSibling?.classList.contains('program-actions'))||row.cells[2],createdCell=document.createElement('td');createdCell.className='program-created-at';createdCell.textContent=formatDateTime(program.createdAt||program.updatedAt);createdCell.title='Fecha de creación del programa';updatedCell.before(createdCell)})})};

// Crear un programa es una decisión breve: iniciar uno nuevo o copiar un patrón existente.
newProgram=function(){const defaultMonth=new Date().toISOString().slice(0,7),sources=[...db.programs],sourceOptions=sources.map(program=>`<option value="${program.id}">${esc(formatMonth(program.month))} · ${esc(formatDateTime(program.createdAt||program.updatedAt))}</option>`).join('');let mode='blank';modal(`<div class="toolbar"><h2>Crear programa</h2><button type="button" data-close>Cerrar</button></div><div class="simple-program-create"><label>Mes<input name="month" type="month" value="${defaultMonth}" required></label><div class="simple-program-choices" role="group" aria-label="Forma de crear el programa"><button type="button" class="simple-program-choice is-selected" data-simple-creation="blank" aria-pressed="true">Nuevo</button><button type="button" class="simple-program-choice" data-simple-creation="copy" aria-pressed="false" ${sources.length?'':'disabled'}>Copiar de…</button></div><label class="simple-program-source" hidden>Programa de origen<select name="sourceProgram">${sourceOptions}</select></label></div><div class="modal-actions"><button type="button" data-close>Cancelar</button><button class="primary">Crear programa</button></div>`,(formData,dialog)=>{const month=formData.get('month'),sourceId=formData.get('sourceProgram'),source=mode==='copy'?db.programs.find(program=>program.id===sourceId):null;if(mode==='copy'&&!source)return formError('Selecciona el programa que quieres copiar.');const createdAt=now(),program={id:uid(),month,createdAt,updatedAt:createdAt,status:'Borrador',assignments:mode==='copy'?copiedAssignmentsForMonth(source,month):blankAssignmentsForMonth(month),creationMode:mode,sourceProgramId:source?.id||''};db.programs.unshift(program);programScope='all';save('Creación de programa',mode==='copy'?`${formatMonth(month)} basado en ${formatMonth(source.month)}`:`${formatMonth(month)} · Nuevo`);dialog.close();openProgram(program.id)});const form=document.querySelector('#modalForm'),sourceField=form.querySelector('.simple-program-source');form.querySelectorAll('[data-simple-creation]').forEach(option=>option.onclick=()=>{mode=option.dataset.simpleCreation;form.querySelectorAll('[data-simple-creation]').forEach(choice=>{const selected=choice===option;choice.classList.toggle('is-selected',selected);choice.setAttribute('aria-pressed',String(selected))});sourceField.hidden=mode!=='copy'})};
const assignmentCardBeforeAvailabilityStatus=assignmentCardMarkup;
assignmentCardMarkup=function(program,assignment,people,compact=false){let markup=assignmentCardBeforeAvailabilityStatus(program,assignment,people,compact),reason=unavailableReasonForAssignment(assignment);markup=markup.replace('<article class="program-slot ',`<article data-program-id="${program.id}" data-assignment-id="${assignment.id}" class="program-slot `);if(!reason)return markup;markup=markup.replace('<article data-program-id=', '<article data-unavailable="true" data-program-id=');markup=markup.replace('class="program-slot ', 'class="program-slot slot-unavailable ');return markup.replace(/<span class="slot-status[^>]*>.*?<\/span>/,`<span class="slot-status unavailable" title="${esc(reason)}" aria-label="No disponible: ${esc(reason)}">No disponible</span>`)};

const addUnavailableCardState=enhanceAssignmentEditors;
enhanceAssignmentEditors=function(){addUnavailableCardState();document.querySelectorAll('.program-slot[data-program-id][data-assignment-id]').forEach(slot=>{const program=db.programs.find(item=>item.id===slot.dataset.programId),assignment=program?.assignments.find(item=>item.id===slot.dataset.assignmentId),reason=assignment&&unavailableReasonForAssignment(assignment);if(!reason)return;slot.classList.add('slot-unavailable');slot.classList.remove('slot-unassigned','calendar-card-interactive');slot.removeAttribute('tabindex');slot.dataset.unavailable='true';let status=slot.querySelector('.slot-status');if(!status){status=document.createElement('span');slot.querySelector('.slot-top')?.append(status)}status.textContent='No disponible';status.className='slot-status unavailable';status.title=reason;status.setAttribute('aria-label',`No disponible: ${reason}`);slot.querySelector('.unassigned-option')?.remove();slot.querySelector('.calendar-empty-actions')?.remove();slot.title=reason})};

function updateProgramAvailability(programId){const program=db.programs.find(item=>item.id===programId);if(!program)return;const changes=configurationChangesForProgram(program),unavailable=changes.unavailable,missing=changes.missing;if(!unavailable.length&&!missing.length)return;const messageParts=[];if(missing.length)messageParts.push(`agregarán ${missing.length} ${newAssignmentLabel(missing.length)}`);if(unavailable.length)messageParts.push(`eliminarán ${unavailable.length} ${assignmentCountLabel(unavailable.length)} no disponibles`);confirmDialog({title:'¿Actualizar programa?',message:`Se ${messageParts.join(' y ')}.`,confirmLabel:'Actualizar programa',onConfirm:()=>{program.assignments=program.assignments.filter(assignment=>!unavailableReasonForAssignment(assignment)).concat(missing.map(assignment=>({...assignment,origin:'configuración'})));program.updatedAt=now();programScope='all';const resultParts=[];if(missing.length)resultParts.push(`se agregaron ${missing.length} ${newAssignmentLabel(missing.length)}`);if(unavailable.length)resultParts.push(`se eliminaron ${unavailable.length} ${assignmentCountLabel(unavailable.length)} no disponibles`);programNotice={programId:program.id,message:`Programa actualizado: ${resultParts.join(' y ')}.`};save('Actualización de programa',`${formatMonth(program.month)}; ${resultParts.join(' y ')}`);openProgram(program.id)}})}

const openProgramBeforeAvailabilityStatus=openProgram;
openProgram=function(id){openProgramBeforeAvailabilityStatus(id);const program=db.programs.find(item=>item.id===id),changes=program&&configurationChangesForProgram(program),unavailable=changes?.unavailable||[],missing=changes?.missing||[];if(!program||(!unavailable.length&&!missing.length))return;const toolbar=document.querySelector('.program-head .toolbar'),tools=toolbar?.querySelector('.program-tools');if(toolbar&&!toolbar.querySelector('.program-config-note')){const note=document.createElement('p');note.className=`program-config-note ${missing.length&&!unavailable.length?'is-new':''}`;if(missing.length&&unavailable.length)note.textContent=`Este programa no coincide con la configuración actual: hay ${missing.length} ${newAssignmentLabel(missing.length)} y ${unavailable.length} ${assignmentCountLabel(unavailable.length)} fuera de configuración.`;else if(missing.length)note.textContent=`Hay ${missing.length} ${newAssignmentLabel(missing.length)} en la configuración actual.`;else note.textContent=`Este programa contiene ${unavailable.length} ${assignmentCountLabel(unavailable.length)} fuera de la configuración actual.`;toolbar.after(note)}if(tools&&!tools.querySelector('[data-update-program]')){const total=missing.length+unavailable.length,button=document.createElement('button');button.type='button';button.className='update-program-button';button.dataset.updateProgram=program.id;button.textContent=`Actualizar programa (${total})`;button.title='Agrega las nuevas asignaciones y quita las que ya no están disponibles';button.onclick=()=>updateProgramAvailability(program.id);tools.append(button)}};

const addProgramAvailabilityIndicators=shell;
shell=function(html){addProgramAvailabilityIndicators(html);document.querySelectorAll('table').forEach(table=>{if(!table.querySelector('button[data-action="openProgram"]'))return;table.querySelectorAll('tr').forEach(row=>{const link=row.querySelector('button[data-action="openProgram"]');if(!link||row.querySelector('.program-availability-indicator'))return;const program=db.programs.find(item=>item.id===link.dataset.id),changes=program&&configurationChangesForProgram(program),missing=changes?.missing.length||0,unavailable=changes?.unavailable.length||0;if(!missing&&!unavailable)return;const indicator=document.createElement('button');indicator.type='button';indicator.className=`program-availability-indicator ${missing&&!unavailable?'is-new':''}`;if(missing&&unavailable){indicator.textContent='⚠ Configuración desactualizada';indicator.title=`Nuevas asignaciones disponibles: ${missing}. No disponibles: ${unavailable}.`}else if(missing){indicator.textContent=`＋ ${missing} ${newAssignmentLabel(missing)}`;indicator.title=`Nuevas asignaciones disponibles (${missing})`}else{indicator.textContent=`⚠ ${unavailable} no disponible${unavailable===1?'':'s'}`;indicator.title=`Abrir ${unavailable} ${assignmentCountLabel(unavailable)} no disponible${unavailable===1?'':'s'} en Advertencias`}indicator.setAttribute('aria-label',indicator.title);indicator.onclick=()=>{programScope=unavailable?'warning':'all';openProgram(program.id)};link.insertAdjacentElement('afterend',indicator)})})};

function render(){if(view==='program'){const p=db.programs[0];return p?openProgram(p.id):newProgram()}({dashboard,participants,types,states,availability,turns,resources,programs,history}[view]||dashboard)()}render();
document.addEventListener('click',event=>{if(event.target.closest('[data-action="openProgram"]'))programScope='all'},true);
document.addEventListener('submit',event=>{if(event.target.id==='monthForm')programScope='all'},true);
